INSERT INTO patient_observation (poid, pid, note_ts, note_text, pain_score) VALUES
  (11001, 13847, '2026-05-11 08:00:00', 'Patient transferred from OR after uncomplicated CABG x3 (LIMA-LAD, SVG-OM, SVG-RCA). Haemodynamically stable. Intubated and sedated with propofol TCI + remifentanil.', 6),
  (11002, 11256, '2026-05-11 07:30:00', 'Post-operative day 1 following emergency Hartmann procedure for perforated diverticulitis. Septic shock ongoing: norepinephrine 0.15 mcg/kg/min to maintain MAP >65 mmHg.', 5),
  (11003, 17291, '2026-05-11 09:15:00', 'ARDS secondary to COVID-19 pneumonia. Day 6 on ICU. Berlin criteria: severe (P/F ratio 98 on PEEP 14, FiO2 0.65). Prone positioning 16 hours/day.', 3),
  (11004, 14538, '2026-05-11 06:45:00', 'Severe TBI following high-speed motor vehicle accident. GCS 8 (E2V2M4) on admission. CT head: bifrontal contusions, right acute subdural haematoma (5mm).', 2),
  (11005, 19012, '2026-05-11 10:00:00', 'Multi-organ failure: cardiogenic shock (EF 15% on TTE), AKI stage 3 (creatinine 620 umol/L), transaminitis (ALT 892, AST 1024). IABP in situ (1:1 counterpulsation).', 7),
  (11006, 12673, '2026-05-11 08:30:00', 'Post-operative day 0. Emergency laparotomy 4 hours ago for perforated peptic ulcer with generalised peritonitis. Graham patch repair performed.', 8),
  (11007, 16184, '2026-05-11 07:00:00', 'Anterior STEMI. Primary PCI to LAD performed 2 hours ago (door-to-balloon 42 min). Drug-eluting stent deployed in mid-LAD, TIMI 3 flow restored.', 7),
  (11008, 18350, '2026-05-11 11:00:00', 'Right MCA ischaemic stroke with left hemiparesis. NIHSS 14. IV thrombolysis (alteplase 0.9 mg/kg) administered at 2.5 hours from symptom onset.', 4),
  (11009, 11729, '2026-05-11 09:00:00', 'Severe acute pancreatitis (Ranson score 5, APACHE II 18). CT abdomen (CECT): 60% pancreatic necrosis (Balthazar grade E).', 9),
  (11010, 15463, '2026-05-11 10:30:00', 'AKI stage 3 secondary to contrast nephropathy (CTPA performed 3 days ago for PE workup). CVVH commenced via right femoral Vascath (Prismax, CVVHDF mode).', 5),
  (11011, 13091, '2026-05-11 06:00:00', 'Heroin overdose. Found unresponsive at home by flatmate, brought in by ambulance. GCS 6 (E1V1M4) on arrival. Airway secured: RSI, intubated.', 2),
  (11012, 17824, '2026-05-11 08:00:00', 'Flame burns sustained in house fire. TBSA 42% (face 4.5%, anterior trunk 18%, bilateral upper limbs 19.5%); mixed partial and full thickness.', 9),
  (11013, 12516, '2026-05-11 12:00:00', 'Post-operative day 1 following orthotopic liver transplantation for alcoholic cirrhosis (Child-Pugh C, MELD score 28, donor-recipient match excellent).', 6),
  (11014, 19347, '2026-05-11 07:15:00', 'Severe diabetic ketoacidosis: venous pH 7.05, glucose 38.2 mmol/L, bicarbonate 4 mmol/L, ketones 6.8 mmol/L (blood), anion gap 32 mmol/L.', 6),
  (11015, 14102, '2026-05-11 10:00:00', 'Severe CAP (CURB-65 score 4). Admitted from ED with type 2 respiratory failure: PaO2 7.2 kPa on 60% Venturi mask, pCO2 7.8 kPa. Intubated on ICU.', 5),
  (11016, 16758, '2026-05-11 08:45:00', 'Massive upper GI haemorrhage. Emergency OGD: Forrest Ia bleeding peptic ulcer (posterior wall duodenum, 2cm diameter). Dual endoscopic therapy performed.', 7),
  (11017, 11893, '2026-05-11 09:30:00', 'Massive PE confirmed on CTPA: bilateral saddle embolism with right heart strain (RV:LV ratio 1.6 on CT, RV dilation and hypokinesis on echo).', 8),
  (11018, 15024, '2026-05-11 07:00:00', 'Bacterial meningitis confirmed: CSF turbid, protein 4.2 g/L, glucose 0.8 mmol/L (blood glucose 5.4, ratio 0.15), WBC 2200 cells/microL (90% PMN).', 9),
  (11019, 18436, '2026-05-11 11:30:00', 'Post right lower lobectomy for stage IIA non-small-cell lung cancer (adenocarcinoma, T2bN0M0). Video-assisted thoracoscopic surgery (VATS) approach.', 7),
  (11020, 13615, '2026-05-11 06:30:00', 'Hypertensive emergency: BP 230/140 mmHg on arrival with confusion, severe occipital headache, visual disturbance and vomiting. CT head: PRES pattern.', 6),
